use vstd::prelude::*;

verus! {

    // Purely functional specification on sequences.
    spec fn is_min_heap_spec(a: Seq<i32>) -> bool {
        let n = a.len();
        // floor(n/2) is the number of parent‐slots
        let half = n / 2;
        // For every parent index i < half we must have:
        //   a[i] <= a[2*i+1]
        // and if the right child exists also
        //   a[i] <= a[2*i+2].
        forall |i: usize|
            i < half ==>
                a[i] <= a[2*i + 1]
                && (2*i + 2 < n ==> a[i] <= a[2*i + 2])
    }

    // Check at run‐time whether a non‐empty Vec<i32> satisfies the min‐heap property.
    fn is_min_heap(a: &Vec<i32>) -> (result: bool)
        requires
            a.len() > 0,
        ensures
            result == is_min_heap_spec(a@)
    {
        let n = a.len();
        let half = n / 2;     // number of internal nodes
        let mut i: usize = 0;
        let mut ok: bool = true;
        // We walk i = 0..half−1.  `ok` records whether *so far*
        // all parents < i satisfied the min‐heap property, or else
        // whether we already found a counter‐example.
        while i < half
            invariant
                // 0 ≤ i ≤ half
                i <= half,

                // If ok==true then for every j<i the two‐child constraints hold
                ok ==>
                    forall |j: usize|
                        j < i ==>
                            a[j] <= a[2*j + 1]
                            && (2*j + 2 < n ==> a[j] <= a[2*j + 2]),

                // If ok==false then there is already some witness j<i that fails
                !ok ==>
                    exists |j: usize|
                        j < i
                        && !(
                            a[j] <= a[2*j + 1]
                            && (2*j + 2 < n ==> a[j] <= a[2*j + 2])
                        ),

            decreases
                half - i,
        {
            if ok {
                // only check children if we have not yet found any failure
                if !(a[i] <= a[2*i + 1]) {
                    ok = false;
                } else if 2*i + 2 < n && !(a[i] <= a[2*i + 2]) {
                    ok = false;
                }
            }
            i += 1;
        }

        // After the loop, i == half, and the invariants tell us exactly:
        //   ok ⇔ (∀ j < half. P(j))
        // which is exactly our spec.
        assert(ok == is_min_heap_spec(a@));

        ok
    }
}

fn main() {
    // (optional quick smoke tests)
    let v1 = vec![1, 2, 3, 4, 5];
    assert!(is_min_heap(&v1));
    let mut v2 = vec![1, 2, 0, 4, 5];
    assert!(!is_min_heap(&v2));
    v2[2] = 2;
    assert!(is_min_heap(&v2));
}